def kvadrat(x):
    return x * x


def je_punoletan(godine):
    if godine >= 18:
        return True
    return False


print(kvadrat(4))
zbir = kvadrat(3) + kvadrat(4)
print("Zbir kvadrata:", zbir)

if je_punoletan(20):
    print("Punoletan")


def samo_ispisuje(x):
    print(x * x)


rezultat = samo_ispisuje(5)
print("Vraćeno:", rezultat)

